const D = { energy:.6, scale:1, density:.4, hue:28, speed:1, x:.5, y:.5, alpha:.92, split:.5, style:'sepia', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const t = K.t;
const drift = 0.9*Math.sin(t*0.61) + 0.5*Math.sin(t*1.43+1.7) + 0.32*Math.sin(t*2.29);
const swell = (K.swell!=null ? K.swell : 0.5+0.5*Math.sin(t*0.4));
const bass = A.bass||0;

// duotone / tritone ramps (RGB 0-255): [shadow, mid, highlight]
const st = P.style;
let c0,c1,c2, hasMid=false;
if (st==='gravure'){ c0=[16,14,18]; c2=[212,208,201]; c1=[110,104,110]; }
else if (st==='blueprint'){ c0=[10,22,60]; c2=[202,232,241]; c1=[58,112,172]; }
else if (st==='duo_pop'){ c0=[92,8,74]; c2=[204,232,120]; c1=[196,84,132]; }
else if (st==='tritone'){ c0=[30,20,46]; c1=[182,92,60]; c2=[236,226,206]; hasMid=true; }
else { c0=[42,26,12]; c2=[242,226,192]; c1=[152,112,70]; } // sepia
// shift ramp by hue param (rotate slightly toward P.hue on the highlight)
const hk = (P.hue-28)/360;
function tintRGB(c){ return [ Math.min(255,c[0]*(1+hk*0.15)), c[1], Math.min(255,c[2]*(1-hk*0.1)) ]; }
c0=tintRGB(c0); c1=tintRGB(c1); c2=tintRGB(c2);

const mid = 0.15 + 0.7*P.split;
function ramp(v){
  // v in [0,1] -> rgb, two-segment through the mid stop
  let r,g,b;
  if (v < mid){ const k=v/mid; r=c0[0]+(c1[0]-c0[0])*k; g=c0[1]+(c1[1]-c0[1])*k; b=c0[2]+(c1[2]-c0[2])*k; }
  else { const k=(v-mid)/(1-mid); r=c1[0]+(c2[0]-c1[0])*k; g=c1[1]+(c2[1]-c1[1])*k; b=c1[2]+(c2[2]-c1[2])*k; }
  return [r,g,b];
}

const BW = Math.max(340, Math.min(460, Math.round(width/2.8)));
const BH = Math.max(120, Math.round(BW*height/width));
if (!S.buf || S.bkey !== BW+'x'+BH){ S.buf = createGraphics(BW, BH); S.bkey = BW+'x'+BH; }
const buf = S.buf;
const feat = 1.4 + 4.6/Math.max(0.35, P.scale);
const con = 0.7 + 2.0*P.energy;
const grain = 0.14*P.density;
const nh = (x,y)=>{ const s=Math.sin(x*12.9898 + y*78.233 + P.seed*3.7)*43758.5453; return s-Math.floor(s); };
const dxo = 0.04*Math.sin(t*0.03) + 0.02*drift;

buf.loadPixels();
const pix = buf.pixels;
for (let y=0; y<BH; y++){
  const ny = y/BH;
  for (let x=0; x<BW; x++){
    const nx = x/BW + dxo;
    let f = Math.sin((nx*feat)*6.283 + t*0.11)
          + Math.sin((ny*feat*0.82)*6.283 - t*0.07 + 1.3)
          + 0.7*Math.sin(((nx+ny)*feat*0.6)*6.283 + t*0.05)
          + 0.6*Math.sin((Math.hypot(nx-0.5,ny-0.5)*feat*1.7)*6.283 - t*0.09 + 2.1);
    let v = 0.5 + 0.155*f;
    v = 0.5 + (v-0.5)*con;
    v += (nh(x,y)-0.5)*grain;
    v = v<0?0:v>1?1:v;
    const c = ramp(v);
    const idx = 4*(y*BW+x);
    pix[idx]=c[0]; pix[idx+1]=c[1]; pix[idx+2]=c[2]; pix[idx+3]=255;
  }
}
buf.updatePixels();

push();
imageMode(CORNER);
blendMode(BLEND);
tint(0,0,100, 100*P.alpha);
image(buf, 0, 0, width, height);
noTint();
// gentle overall breathing bloom on highlights (ADD, broad, slow) so it lives
blendMode(ADD); noStroke();
